#!/usr/bin/env node
// Differential harness: runs the reference executable and the Node port with the
// same argv and compares stdout + exit status (and, loosely, stderr).
//
// Usage:
//   node /workspace/difftest.mjs cases.json      # JSON array of argv arrays
//   node /workspace/difftest.mjs --fuzz N [seed]
//   node /workspace/difftest.mjs -- --a X --b Y --c z --d z   # single case
//
// Not part of the deliverable; lives outside /output on purpose.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test15_executable';
const PORT = '/output/test15.mjs';

function runRef(argv) {
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

function runPort(argv) {
  const r = spawnSync(process.execPath, [PORT, ...argv], {
    encoding: 'utf8',
    maxBuffer: 1 << 28,
  });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

// The PyInstaller footer embeds the pid, which differs per run by design.
function normErr(text) {
  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

export function compare(argv) {
  const a = runRef(argv);
  const b = runPort(argv);
  const problems = [];
  if (a.out !== b.out) problems.push('stdout');
  if (a.code !== b.code) problems.push('exit');
  if (normErr(a.err) !== normErr(b.err)) problems.push('stderr');
  return { argv, ref: a, port: b, problems };
}

// ---- pseudo-random case generation (deterministic, seeded) -----------------

function makeRng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}

const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const NASTY = [
  '', ' ', '  ', '\t', '\n', '1', '11', '111', '1z', 'z1', '0', 'O', 'I', 'l',
  "'", '"', '\\', 'a\'b"c', 'é', '€', '😀', 'z ', ' z', 'z ', 'z　',
  '-5', '-5.5', '-x', '--a', 'a=b', 'z​', 'ü', '', 'hello world',
];

function randStr(rng, alphabet, maxLen) {
  const n = Math.floor(rng() * (maxLen + 1));
  let out = '';
  for (let i = 0; i < n; i += 1) {
    out += alphabet[Math.floor(rng() * alphabet.length)];
  }
  return out;
}

const ANY = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ'
  + '[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~éü€😀\t ';

export function genCases(count, seed) {
  const rng = makeRng(seed);
  const cases = [];
  for (let i = 0; i < count; i += 1) {
    const pick = (kind) => {
      const roll = rng();
      if (roll < 0.15) return NASTY[Math.floor(rng() * NASTY.length)];
      if (kind === 'b58' && roll < 0.85) return randStr(rng, B58, 40);
      return randStr(rng, ANY, 30);
    };
    cases.push(['--a', pick('any'), '--b', pick('any'), '--c', pick('b58'), '--d', pick('b58')]);
  }
  return cases;
}

// ---- entry -----------------------------------------------------------------

const argv = process.argv.slice(2);
let cases;
if (argv[0] === '--fuzz') {
  cases = genCases(Number(argv[1] || 100), Number(argv[2] || 12345));
} else if (argv[0] === '--') {
  cases = [argv.slice(1)];
} else if (argv[0]) {
  cases = JSON.parse(readFileSync(argv[0], 'utf8'));
} else {
  console.error('nothing to do');
  process.exit(64);
}

let failures = 0;
for (const argvCase of cases) {
  const result = compare(argvCase);
  if (result.problems.length > 0) {
    failures += 1;
    console.log('MISMATCH', result.problems.join(','), JSON.stringify(argvCase));
    console.log('  ref  code=%d out=%j', result.ref.code, result.ref.out);
    console.log('  port code=%d out=%j', result.port.code, result.port.out);
    if (result.problems.includes('stderr')) {
      console.log('  ref  err=%j', normErr(result.ref.err));
      console.log('  port err=%j', normErr(result.port.err));
    }
  }
}
console.log(`\n${cases.length - failures}/${cases.length} cases matched`);
process.exit(failures > 0 ? 1 : 0);

#!/usr/bin/env node
// test15.mjs — Node.js port of dataset/base58/test15.py
//
// Original:
//     import argparse
//     import base58
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//     parser.add_argument('--b', type=str, required=True)
//     parser.add_argument('--c', type=str, required=True)
//     parser.add_argument('--d', type=str, required=True)
//     args = parser.parse_args()
//
//     enc1 = base58.b58encode(args.a.encode())  # 编码字符串1
//     enc2 = base58.b58encode(args.b.encode())  # 编码字符串2
//     dec1 = base58.b58decode(args.c)  # 解码Base58字符串1
//     dec2 = base58.b58decode(args.d)  # 解码Base58字符串2
//     print(enc1)
//     print(enc2)
//     print(dec1)
//     print(dec2)
//
// All four values are computed before anything is printed, so a decoding
// failure produces no stdout at all — just the traceback and exit status 1.

import { ArgumentParser } from './lib/cli/argparse.mjs';
import { PythonError, SystemExit } from './lib/python/errors.mjs';
import { encodeUtf8 } from './lib/python/unicode.mjs';
import { printBytes } from './lib/python/print.mjs';
import { reportFatal } from './lib/python/traceback.mjs';
import { b58decode, b58encode } from './lib/base58/index.mjs';

/** Program name used in usage/help text, as in the reference build. */
const PROG = 'test15_executable';
const SOURCE_FILE = 'test15.py';
const SCRIPT_NAME = 'test15';

/**
 * The `<module>` frames a b58decode failure is reported against.  `colno` /
 * `endColno` delimit `base58.b58decode(args.X)` within the source line, which is
 * what the carets underline.
 */
const DECODE_FRAME = {
  c: { file: SOURCE_FILE, line: 13, name: '<module>', colno: 7, endColno: 31 },
  d: { file: SOURCE_FILE, line: 14, name: '<module>', colno: 7, endColno: 31 },
};

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { required: true });
  parser.addArgument(['--b'], { required: true });
  parser.addArgument(['--c'], { required: true });
  parser.addArgument(['--d'], { required: true });
  return parser;
}

/**
 * @param {string[]} argv arguments after the script name
 * @returns {number} process exit status
 */
export function main(argv) {
  const args = buildParser().parseArgs(argv);

  const enc1 = b58encode(encodeUtf8(args.a)); // 编码字符串1
  const enc2 = b58encode(encodeUtf8(args.b)); // 编码字符串2

  let dec1;
  let dec2;
  try {
    dec1 = b58decode(args.c); // 解码Base58字符串1
    dec2 = b58decode(args.d); // 解码Base58字符串2
  } catch (error) {
    if (!(error instanceof PythonError)) throw error;
    const frame = dec1 === undefined ? DECODE_FRAME.c : DECODE_FRAME.d;
    reportFatal(error, frame, SCRIPT_NAME, process.pid);
    return 1;
  }

  printBytes(enc1);
  printBytes(enc2);
  printBytes(dec1);
  printBytes(dec2);
  return 0;
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  if (!(error instanceof SystemExit)) throw error;
  process.exitCode = error.code;
}
