// lib/python/width.mjs
//
// `traceback._display_width`: how much horizontal space a source segment takes
// on a fixed-width device, so that caret runs line up under wide characters.
//
// CPython consults `unicodedata.east_asian_width`.  The ranges below cover the
// 'W' and 'F' (wide and fullwidth) blocks — CJK, Hangul, Kana, fullwidth forms
// and the pictographic planes — which is everything that can realistically
// appear in the source lines this program reports on.

import { toCodePoints } from './unicode.mjs';

/** Inclusive [start, end] ranges of wide / fullwidth code points. */
const WIDE_RANGES = [
  [0x1100, 0x115f], [0x231a, 0x231b], [0x2329, 0x232a],
