  [0x1f57a, 0x1f57a], [0x1f595, 0x1f596], [0x1f5a4, 0x1f5a4],
  [0x1f5fb, 0x1f64f], [0x1f680, 0x1f6c5], [0x1f6cc, 0x1f6cc],
  [0x1f6d0, 0x1f6d2], [0x1f6d5, 0x1f6d7], [0x1f6eb, 0x1f6ec],
  [0x1f6f4, 0x1f6fc], [0x1f7e0, 0x1f7eb], [0x1f90c, 0x1f93a],
  [0x1f93c, 0x1f945], [0x1f947, 0x1f978], [0x1f97a, 0x1f9cb],
  [0x1f9cd, 0x1f9ff], [0x1fa70, 0x1fa74], [0x1fa78, 0x1fa7a],
  [0x1fa80, 0x1fa86], [0x1fa90, 0x1faa8], [0x1fab0, 0x1fab6],
  [0x1fac0, 0x1fac2], [0x1fad0, 0x1fad6],
  [0x20000, 0x2fffd], [0x30000, 0x3fffd],
];

function isWide(codePoint) {
  for (const [start, end] of WIDE_RANGES) {
    if (codePoint < start) return false; // ranges are ascending
    if (codePoint <= end) return true;
  }
  return false;
}

function isAsciiOnly(text) {
  for (let i = 0; i < text.length; i += 1) {
    if (text.charCodeAt(i) > 0x7f) return false;
  }
  return true;
}

/**
 * `_display_width(line, offset)` — width of the first `offset` characters.
 *
 * @param {string} line
 * @param {number} offset character count
 * @returns {number}
 */
export function displayWidth(line, offset) {
  // CPython's fast path: for an ASCII line the width equals the offset, even
  // when the offset runs past the end of the line.
  if (isAsciiOnly(line)) return offset;
  let width = 0;
  let seen = 0;
  for (const codePoint of toCodePoints(line)) {
    if (seen >= offset) break;
    width += isWide(codePoint) ? 2 : 1;
    seen += 1;
  }
  return width;
}

