import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync, chmodSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';

// scenarios: {name, setup(dir)}  ; cases: argv arrays
export function run(scenarios, cases) {
  let fails = 0, total = 0;
  for (const sc of scenarios) {
    const dir = mkdtempSync(tmpdir() + '/sc-');
    try {
      sc.setup(dir);
    } catch (e) { console.log('SETUP FAIL', sc.name, e.message); continue; }
    for (const argv of cases) {
      total++;
      const r = spawnSync(process.execPath, ['/workspace/difftest.mjs', '--', ...argv],
        { cwd: dir, encoding: 'utf8', maxBuffer: 1<<28 });
      const out = r.stdout ?? '';
      if (!/1\/1 cases matched/.test(out)) {
        fails++;
        console.log('=== DIVERGE scenario=%s argv=%s', sc.name, JSON.stringify(argv));
        console.log(out.trim());
        if (r.stderr) console.log('  harness stderr:', r.stderr.trim());
      }
    }
    try { rmSync(dir, {recursive:true, force:true}); } catch {}
  }
  console.log(`\n${total-fails}/${total} probes matched`);
}
